mapper.select:
select * from chat_history where appId=#{appId} and isDelete=0
and (createTime<#{beforeTime} or (createTime=#{beforeTime} and id<#{beforeId}))
order by createTime desc,id desc limit #{limit}

mapper.sql:
from chat_history where isDelete=0 and message like #{query}
and appId=#{appId}
and userId=#{userId}
and messageType=#{type}
and createTime>=#{start}
and createTime<=#{end}
